			if (f == null) continue;
			JsonObject o = new JsonObject();
			o.addProperty("qty",        f.qty);
			o.addProperty("price_each", f.priceEach);
			if (f.tradedAt != null) o.addProperty("traded_at", f.tradedAt);
			arr.add(o);
		}
		return arr;
	}

