			.append(FlipItemPanel.escapeHtml(cp.name)).append("</b></font>");
		if (cp.partial)
		{
			name.append(" <font color='#FFC077'>· partial</font>");
		}
		name.append("</html>");
		JLabel nameLbl = new JLabel(name.toString());
		nameLbl.setFont(Fonts.SM);
