	private static String formatHoursLocal(double h)
	{
		if (h < 1.0)
		{
			long mins = Math.round(h * 60);
			return Math.max(1, mins) + "m fill";
		}
		String s = String.format("%.1f", h);
		if (s.endsWith(".0")) s = s.substring(0, s.length() - 2);
		return s + "h fill";
	}

