			: (plugin != null ? plugin.flipEtaBuy(flip.itemId)  : null);
		Integer etaSell = flip.etaSellMinutes != null ? flip.etaSellMinutes
			: (plugin != null ? plugin.flipEtaSell(flip.itemId) : null);
		if (etaBuy != null && etaSell != null && etaBuy + etaSell > 0)
