			etaLabel.setFont(Fonts.SM);
			etaLabel.setForeground(new Color(0x888888));
			etaLabel.setToolTipText("<html>Est. flip time at 07Flip prices — buy fills ~"
				+ formatMinutes(etaBuy) + ", sell fills ~" + formatMinutes(etaSell)
