	private static JPanel ageRow(JLabel priceLabel, Integer ageMinutes)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		row.add(priceLabel, BorderLayout.CENTER);

		String age = InsightsPanel.ageSuffix(ageMinutes);
		if (age != null)
		{
			JLabel ageLabel = new JLabel(age);
			ageLabel.setFont(Fonts.SM);
			ageLabel.setForeground(new Color(0x888888));
			ageLabel.setToolTipText("Time since this price last traded");
			row.add(ageLabel, BorderLayout.EAST);
		}
		return row;
	}

	public static String formatGp(long amount)
	{
		return String.format("%,d", amount);
	}

	public static String formatMinutes(int minutes)
	{
		if (minutes < 60)
		{
			return minutes + "m";
		}
		int h = minutes / 60;
		int m = minutes % 60;
		return m == 0 ? h + "h" : h + "h" + m + "m";
	}

	public static String formatGpCompact(long amount)
	{
		long abs = Math.abs(amount);
		if (abs >= 1_000_000_000L)
		{
			return trim(String.format("%.2f", amount / 1_000_000_000.0)) + "B";
		}
		if (abs >= 1_000_000L)
		{
			return trim(String.format("%.2f", amount / 1_000_000.0)) + "M";
		}
		if (abs >= 1_000L)
		{
			return trim(String.format("%.1f", amount / 1_000.0)) + "K";
		}
		return String.valueOf(amount);
	}

	private static String trim(String s)
	{
		int dot = s.indexOf('.');
		if (dot < 0)
		{
			return s;
		}
		int end = s.length();
		while (end > dot && s.charAt(end - 1) == '0')
		{
			end--;
		}
		if (end > dot && s.charAt(end - 1) == '.')
		{
			end--;
		}
		return s.substring(0, end);
	}

	public static String escapeHtml(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

