	private static Color signColor(double v)
	{
		if (v > 0)
		{
			return PROFIT_COL;
		}
		if (v < 0)
		{
			return LOSS_COL;
		}
		return Color.LIGHT_GRAY;
	}

	private static Color crossColor(String cross)
	{
		if ("bullish".equalsIgnoreCase(cross))
		{
			return PROFIT_COL;
		}
		if ("bearish".equalsIgnoreCase(cross))
		{
			return LOSS_COL;
		}
		return Color.WHITE;
	}

	private static Color rangePositionColor(double positionPct)
	{
		if (positionPct <= 25)
		{
			return PROFIT_COL;
		}
		if (positionPct >= 75)
		{
			return LOSS_COL;
		}
		return Color.WHITE;
	}

	private static String daysAgo(int days)
	{
		if (days <= 0)
		{
			return "today";
		}
		if (days == 1)
		{
			return "yesterday";
		}
		return days + " days ago";
	}

	private static String formatHours(double hours)
	{
		if (hours < 1)
		{
			return Math.max(1, Math.round(hours * 60)) + "m";
		}
		if (hours < 48)
		{
			return String.format("%.1fh", hours);
		}
		return String.format("%.1fd", hours / 24);
	}

